import java.util.ArrayList;
import java.util.List;

class Song {
    private String title;
    private String artist;

    public Song(String title, String artist) {
        this.title = title;
        this.artist = artist;
    }

    public String getInfo() { return title + " by " + artist; }
}

class Playlist {
    private String name;
    private List<Song> songs = new ArrayList<>(); // Weak Has-A

    public Playlist(String name) {
        this.name = name;
    }

    // Injected externally: Playlist does not own Song creation or lifecycle
    public void addSong(Song song) {
        this.songs.add(song);
    }

    public void playAll() {
        System.out.println("Playing Playlist: " + name);
        for (Song s : songs) {
            System.out.println(" >> Now Playing: " + s.getInfo());
        }
    }
}

public class AggregationDemo {
    public static void main(String[] args) {
        Song s1 = new Song("Bohemian Rhapsody", "Queen");
        Song s2 = new Song("Hotel California", "Eagles");

        Playlist rockClassics = new Playlist("Classic Rock");
        rockClassics.addSong(s1);
        rockClassics.addSong(s2);

        Playlist roadTrip = new Playlist("Road Trip Vibes");
        roadTrip.addSong(s1); // The same Song object is aggregated in another playlist!

        rockClassics.playAll();
        // If rockClassics is set to null, s1 and s2 still exist in roadTrip!
    }
}

