import java.util.ArrayList;
import java.util.List;

class Athlete {
    private String name;
    private String position;

    public Athlete(String name, String position) {
        this.name = name;
        this.position = position;
    }

    public String getDossier() { return name + " (" + position + ")"; }
}

class Team {
    private String teamName;
    private List<Athlete> roster; // Aggregation

    public Team(String teamName, List<Athlete> initialRoster) {
        this.teamName = teamName;
        // Aggregating pre-existing athlete objects
        this.roster = new ArrayList<>(initialRoster);
    }

    public void displayRoster() {
        System.out.println("Team: " + teamName);
        for (Athlete a : roster) {
            System.out.println(" - " + a.getDossier());
        }
    }
}

public class TeamDemo {
    public static void main(String[] args) {
        Athlete p1 = new Athlete("LeBron James", "Forward");
        Athlete p2 = new Athlete("Stephen Curry", "Guard");

        List<Athlete> allStars = new ArrayList<>();
        allStars.add(p1);
        allStars.add(p2);

        Team usaTeam = new Team("Team USA", allStars);
        usaTeam.displayRoster();
    }
}

