import java.util.ArrayList;
import java.util.List;

class Track {
    private String isrc;
    private String title;
    public Track(String isrc, String title) {
        this.isrc = isrc;
        this.title = title;
    }
    public String getDisplay() {
        return title + " (" + isrc + ")";
    }
}

class MusicPlaylist {
    private String name;
    private List<Track> tracks = new ArrayList<>();
    public MusicPlaylist(String name) {
        this.name = name;
    }
    public void addTrack(Track t) {
        tracks.add(t);
    }
    public void showTracklist() {
        System.out.println("=== Playlist: " + name + " ===");
        for (Track t : tracks) {
            System.out.println(" - " + t.getDisplay());
        }
    }
}

public class PlaylistApp {
    public static void main(String[] args) {
        Track t1 = new Track("US-100", "Midnight City");
        Track t2 = new Track("US-200", "Starlight");

        MusicPlaylist favs = new MusicPlaylist("Favorites");
        favs.addTrack(t1);
        favs.addTrack(t2);

        MusicPlaylist night = new MusicPlaylist("Night Drive");
        night.addTrack(t1);

        favs.showTracklist();
        night.showTracklist();
    }
}

import java.util.ArrayList;
import java.util.List;

class SoftwareEngineer {
    private String name;
    private String role;
    public SoftwareEngineer(String name, String role) {
        this.name = name;
        this.role = role;
    }
    public String getBadge() {
        return name + " [" + role + "]";
    }
}

class EngineeringTeam {
    private String projectCodename;
    private List<SoftwareEngineer> members = new ArrayList<>();
    public EngineeringTeam(String projectCodename) {
        this.projectCodename = projectCodename;
    }
    public void recruit(SoftwareEngineer eng) {
        members.add(eng);
    }
    public void disbandTeam() {
        System.out.println("Disbanding team for project: " + projectCodename);
        members.clear();
        System.out.println("Team cleared. Engineers remain active in company pool.");
    }
    public int getMemberCount() {
        return members.size();
    }
}

public class TeamApp {
    public static void main(String[] args) {
        SoftwareEngineer e1 = new SoftwareEngineer("Linus", "Architect");
        SoftwareEngineer e2 = new SoftwareEngineer("Ken", "Systems");

        EngineeringTeam team = new EngineeringTeam("Project Apollo");
        team.recruit(e1);
        team.recruit(e2);

        System.out.println("Active members: " + team.getMemberCount());
        team.disbandTeam();
        System.out.println("Survivor: " + e1.getBadge());
    }
}

