import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

class Painting {
    private String title;
    public Painting(String title) { this.title = title; }
    public String getTitle() { return title; }
}

class ArtGallery {
    private String galleryName;
    private List<Painting> paintings = new ArrayList<>();

    public ArtGallery(String galleryName) { this.galleryName = galleryName; }
    public void exhibit(Painting p) { paintings.add(p); }

    public List<Painting> getPaintings() {
        return Collections.unmodifiableList(paintings);
    }

    public int count() { return paintings.size(); }
}

public class GalleryBugApp {
    public static void main(String[] args) {
        ArtGallery gallery = new ArtGallery("The Louvre");
        gallery.exhibit(new Painting("Mona Lisa"));

        try {
            gallery.getPaintings().add(new Painting("Forgery"));
        } catch (UnsupportedOperationException e) {
            System.out.println("Gallery protected: Modification rejected!");
        }
        System.out.println("Exhibits count: " + gallery.count());
    }
}

import java.util.ArrayList;
import java.util.List;

class CommercialAircraft {
    private String callsign;
    private int altitudeFt;
    private int speedKnots;

    public CommercialAircraft(String callsign, int altitudeFt, int speedKnots) {
        this.callsign = callsign;
        this.altitudeFt = altitudeFt;
        this.speedKnots = speedKnots;
    }

    public String getRadarBlip() {
        return "[" + callsign + "] Alt: " + altitudeFt + "ft, Spd: " + speedKnots + "kts";
    }
}

class RadarSector {
    private String sectorId;
    private List<CommercialAircraft> trackedAircraft = new ArrayList<>();

    public RadarSector(String sectorId) {
        this.sectorId = sectorId;
    }

    public void handoffIn(CommercialAircraft ac) {
        trackedAircraft.add(ac);
    }

    public void handoffOut(CommercialAircraft ac) {
        trackedAircraft.remove(ac);
    }

    public void scanSector() {
        System.out.println("=== Radar Sweep Sector: " + sectorId + " ===");
        if (trackedAircraft.isEmpty()) {
            System.out.println("Sector Clear");
        } else {
            for (CommercialAircraft ac : trackedAircraft) {
                System.out.println(" > " + ac.getRadarBlip());
            }
        }
    }
}

public class AtcApp {
    public static void main(String[] args) {
        CommercialAircraft ua = new CommercialAircraft("UA101", 32000, 450);
        CommercialAircraft dl = new CommercialAircraft("DL404", 28000, 420);

        RadarSector sector = new RadarSector("SECTOR-ZNY");
        sector.handoffIn(ua);
        sector.handoffIn(dl);
        sector.scanSector();

        sector.handoffOut(ua);
        sector.scanSector();
    }
}
